import java.io.*;import java.nio.file.*;import java.util.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.baksmali.*;import com.android.tools.smali.baksmali.Adaptors.*;import com.android.tools.smali.baksmali.formatter.*;
class CompareDex {static Map<String,ClassDef> load(String p)throws Exception {var m=new TreeMap<String,ClassDef>();for(var c:DexFileFactory.loadDexFile(new File(p),Opcodes.forDexVersion(39)).getClasses())m.put(c.getType(),c);return m;}static String normalized(String s){return s.replaceAll("(?m)^(\\.field .* static .*:Z) = false$", "$1");}static String text(ClassDef c)throws Exception {var s=new StringWriter();var o=new BaksmaliOptions();o.apiLevel=28;new ClassDefinition(o,c).writeTo(new BaksmaliWriter(s));return s.toString();}public static void main(String[] a)throws Exception{var x=load(a[0]);var y=load(a[1]);if(!x.keySet().equals(y.keySet()))throw new Exception("class set changed");var changed=new ArrayList<String>();for(var k:x.keySet())if(!normalized(text(x.get(k))).equals(normalized(text(y.get(k)))))changed.add(k);String expected="Lcom/android/systemui/bouncer/ui/composable/BouncerContentKt$BouncerContentLayout$3$1;";if(!changed.equals(List.of(expected)))throw new Exception("unexpected semantic class delta "+changed);for(var k:changed){String n=k.substring(1,k.length()-1).replace("/","_");Files.writeString(Path.of(a[2]+"-"+n+"-old"),text(x.get(k)));Files.writeString(Path.of(a[2]+"-"+n+"-new"),text(y.get(k)));}Files.writeString(Path.of(a[2]),text(y.get(expected)));System.out.println("classes="+x.size()+" changed="+changed);}}
